/**
 * E-commerce SEO checklist data for /e-commerce-seo-checklists.
 * Row format: [title, why/how, impact (H/M/L), priority (1 = do first, 2, 3), tools, manual (true = needs a person, false = tool-checkable or automatable)]
 * Item ids are derived from the title, so edit titles with care: visitors' saved progress is keyed on them.
 */
import type { ChecklistCategory, ChecklistItem, Impact, Priority } from "./types";

type Row = [title: string, detail: string, impact: "H" | "M" | "L", priority: 1 | 2 | 3, tools: string, manual: boolean];

const IMPACT: Record<"H" | "M" | "L", Impact> = { H: "high", M: "medium", L: "low" };
const slug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 70);

function build(cat: string, rows: Row[]): ChecklistItem[] {
  return rows.map(([title, detail, i, p, tools, manual]) => ({
    id: `${cat}-${slug(title)}`,
    title,
    detail,
    impact: IMPACT[i],
    priority: `P${p}` as Priority,
    tools: tools.split(",").map((t) => t.trim()).filter(Boolean),
    manual,
  }));
}

